use std::f32::consts::TAU;

/// Every generated texture is this many pixels square, tiling seamlessly.
pub const SIZE: usize = 128;

/// Pattern scale (noise period, cells per tile), swirl, crust cover and crack width: the look's own tuning,
/// not a traced constant.
const PATTERN: i32 = 4;
const WARP: f32 = 0.6;
const CRUST_COVER: f32 = 0.45;
const CRACK: f32 = 0.08;

/// `mulberry32`: a small, fast, seedable PRNG, floats in `[0, 1)`.
struct Rng(u32);

impl Rng {
    fn next(&mut self) -> f32 {
        self.0 = self.0.wrapping_add(0x6D2B_79F5);
        let mut t = self.0;
        t = (t ^ (t >> 15)).wrapping_mul(t | 1);
        t ^= t.wrapping_add((t ^ (t >> 7)).wrapping_mul(t | 61));
        (t ^ (t >> 14)) as f32 / 4294967296.0
    }
}

/// Tileable Perlin noise: a permutation and a gradient per cell, each wrapped to a given period so it repeats
/// without a seam (`perlin`'s own `rem_euclid`), `fbm` layering it at doubling frequencies.
struct Noise {
    perm: [u8; 256],
    grad: Vec<(f32, f32)>,
}

fn make_noise(seed: u32) -> Noise {
    let mut rng = Rng(seed);
    let mut perm: [u8; 256] = std::array::from_fn(|i| i as u8);
    for i in (1..=255).rev() {
        let j = (rng.next() * (i as f32 + 1.0)) as usize;
        perm.swap(i, j.min(i));
    }
    let grad = (0..256).map(|_| { let a = rng.next() * TAU; (a.cos(), a.sin()) }).collect();
    Noise { perm, grad }
}

impl Noise {
    fn p(&self, i: i32) -> i32 {
        self.perm[i.rem_euclid(256) as usize] as i32
    }

    fn perlin(&self, x: f32, y: f32, period: i32) -> f32 {
        let period = period.max(1);
        let (xi, yi) = (x.floor() as i32, y.floor() as i32);
        let (fx, fy) = (x - xi as f32, y - yi as f32);
        let (i0, i1) = (xi.rem_euclid(period), (xi + 1).rem_euclid(period));
        let (j0, j1) = (yi.rem_euclid(period), (yi + 1).rem_euclid(period));
        let grad_at = |i: i32, j: i32| self.grad[self.p(self.p(i) + j) as usize];
        let dot = |i: i32, j: i32, ox: f32, oy: f32| { let (gx, gy) = grad_at(i, j); gx * ox + gy * oy };
        let fade = |t: f32| t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
        let (u, v) = (fade(fx), fade(fy));
        let top = dot(i0, j0, fx, fy) + (dot(i1, j0, fx - 1.0, fy) - dot(i0, j0, fx, fy)) * u;
        let bot = dot(i0, j1, fx, fy - 1.0) + (dot(i1, j1, fx - 1.0, fy - 1.0) - dot(i0, j1, fx, fy - 1.0)) * u;
        top + (bot - top) * v
    }

    fn fbm(&self, u: f32, v: f32, period: i32, octaves: u32) -> f32 {
        let (mut sum, mut amp, mut f, mut norm) = (0.0, 0.5, 1.0, 0.0);
        for _ in 0..octaves {
            let pf = ((period as f32 * f).min(256.0)) as i32;
            sum += amp * self.perlin(u * pf as f32, v * pf as f32, pf);
            norm += amp;
            amp *= 0.5;
            f *= 2.0;
        }
        sum / norm
    }
}

/// Tileable Worley (cellular) noise: one random point per cell of a `c` x `c` grid, wrapping at its edges;
/// `sample` returns the nearest and second-nearest distances (`F1`, `F2`, in cell units).
struct Worley {
    points: Vec<(f32, f32)>,
    c: i32,
}

fn make_worley(seed: u32, c: i32) -> Worley {
    let mut rng = Rng(seed ^ 0x9e37_79b9);
    let points = (0..c * c).map(|_| (rng.next(), rng.next())).collect();
    Worley { points, c }
}

impl Worley {
    fn sample(&self, u: f32, v: f32) -> (f32, f32) {
        let (px, py) = (u * self.c as f32, v * self.c as f32);
        let (cx, cy) = (px.floor() as i32, py.floor() as i32);
        let (mut f1, mut f2) = (f32::MAX, f32::MAX);
        for dy in -1..=1 {
            for dx in -1..=1 {
                let (nx, ny) = (cx + dx, cy + dy);
                let (wx, wy) = (nx.rem_euclid(self.c), ny.rem_euclid(self.c));
                let (ox, oy) = self.points[(wy * self.c + wx) as usize];
                let d = ((px - (nx as f32 + ox)).powi(2) + (py - (ny as f32 + oy)).powi(2)).sqrt();
                if d < f1 {
                    f2 = f1;
                    f1 = d;
                } else if d < f2 {
                    f2 = d;
                }
            }
        }
        (f1, f2)
    }
}

fn clamp01(x: f32) -> f32 {
    x.clamp(0.0, 1.0)
}
fn smoothstep(a: f32, b: f32, x: f32) -> f32 {
    let t = clamp01((x - a) / (b - a));
    t * t * (3.0 - 2.0 * t)
}
fn mix(a: f32, b: f32, t: f32) -> f32 {
    a + (b - a) * t
}
fn mix3(a: [f32; 3], b: [f32; 3], t: f32) -> [f32; 3] {
    std::array::from_fn(|i| mix(a[i], b[i], t))
}
fn scale3(c: [f32; 3], k: f32) -> [f32; 3] {
    c.map(|v| v * k)
}
/// `fbm` runs about `[-0.7, 0.7]`: recentred into `[0, 1]`.
fn to01(n: f32) -> f32 {
    clamp01(n / 1.1 + 0.5)
}

const CORE: [f32; 3] = [0.0, 0.0, 0.0];
const HOT: [f32; 3] = [0.6, 0.0, 0.0];
const MID: [f32; 3] = [0.5216, 0.2196, 0.2196];
const DARK: [f32; 3] = [0.3608, 0.0588, 0.0196];
const CRUST_COLOUR: [f32; 3] = [0.1686, 0.1255, 0.1098];
const ROCK: [f32; 3] = [0.2392, 0.2118, 0.2];

fn ash_colour() -> [f32; 3] {
    mix3(ROCK, [0.7765, 0.7451, 0.7137], 0.5)
}

/// The molten colour gradient: dark crust, through mid and hot, to the (here black) core.
fn ramp(t: f32) -> [f32; 3] {
    if t < 0.38 {
        mix3(DARK, MID, t / 0.38)
    } else if t < 0.68 {
        mix3(MID, HOT, (t - 0.38) / 0.30)
    } else if t < 0.92 {
        mix3(HOT, CORE, (t - 0.68) / 0.24)
    } else {
        CORE
    }
}

/// Four seamless `SIZE` x `SIZE` RGBA8 textures sharing one generation pass: the hot, flowing surface
/// (`lava`), its cooling, cracked skin (`crust`), the solid rock it leaves (`basalt`), and the ash settling
/// over it (`ash`).
pub struct LavaTextures {
    pub lava: Vec<u8>,
    pub crust: Vec<u8>,
    pub basalt: Vec<u8>,
    pub ash: Vec<u8>,
}

pub fn generate(seed: u32) -> LavaTextures {
    let noise = make_noise(seed);
    let plates = make_worley(seed, PATTERN * 2);
    let vesicle = make_worley(seed.wrapping_add(101), PATTERN * 4);
    let mut grain = Rng(seed.wrapping_add(55));
    let ash = ash_colour();

    let th_lava = 0.85 - CRUST_COVER * 0.7;
    let th_crust = 0.85 - (CRUST_COVER + 0.55).min(1.0) * 0.7;
    let crack_c = CRACK * 0.55;

    let mut out = LavaTextures {
        lava: vec![0u8; SIZE * SIZE * 4],
        crust: vec![0u8; SIZE * SIZE * 4],
        basalt: vec![0u8; SIZE * SIZE * 4],
        ash: vec![0u8; SIZE * SIZE * 4],
    };

    for y in 0..SIZE {
        for x in 0..SIZE {
            let (u, v) = ((x as f32 + 0.5) / SIZE as f32, (y as f32 + 0.5) / SIZE as f32);

            let wu = u + WARP * 0.14 * noise.fbm(u + 0.13, v + 0.71, PATTERN, 3);
            let wv = v + WARP * 0.14 * noise.fbm(u + 0.57, v + 0.29, PATTERN, 3);

            let n = to01(noise.fbm(wu, wv, PATTERN, 5));
            let ridge = clamp01(1.0 - noise.fbm(wu + 0.37, wv + 0.11, PATTERN * 2, 4).abs() * 2.4).powi(3);
            let pn = to01(noise.fbm(u + 0.91, v + 0.43, PATTERN, 4));
            let fine = to01(noise.fbm(u + 0.2, v + 0.8, (PATTERN * 8).min(128), 2));

            let (f1, f2) = plates.sample(wu, wv);
            let e = f2 - f1;

            let heat = clamp01(0.1 + n * 0.8 + ridge * 0.45);
            let molten = ramp(heat);
            let plate_colour = scale3(mix3(CRUST_COLOUR, ROCK, 0.2 + 0.5 * fine), 0.8 + 0.4 * smoothstep(0.0, 0.5, e));

            let rim = 1.0 - smoothstep(CRACK, CRACK + 0.12, e);
            let mask = smoothstep(th_lava - 0.07, th_lava + 0.07, pn) * smoothstep(CRACK, CRACK + 0.05, e);
            let lava_px = mix3(molten, mix3(plate_colour, MID, rim * 0.5), mask);

            let rim_c = 1.0 - smoothstep(crack_c, crack_c + 0.10, e);
            let mask_c = smoothstep(th_crust - 0.07, th_crust + 0.07, pn) * smoothstep(crack_c, crack_c + 0.05, e);
            let crust_px = mix3(ramp(heat * 0.72), mix3(plate_colour, DARK, rim_c * 0.6), mask_c);

            let (b1, b2) = vesicle.sample(u, v);
            let eb = b2 - b1;
            let mut k = 0.7 + to01(noise.fbm(u + 0.33, v + 0.66, PATTERN * 2, 4)) * 0.6 + (fine - 0.5) * 0.15;
            if b1 < 0.13 {
                k *= 0.55 + b1 * 3.0;
            }
            if eb < 0.04 {
                k *= 0.55 + eb * 8.0;
            }
            let basalt_px = scale3(ROCK, k);

            let ash_k = 0.82 + fine * 0.3 + (grain.next() - 0.5) * 0.12 - if eb < 0.03 { 0.1 } else { 0.0 };
            let ash_px = scale3(ash, ash_k);

            let i = (y * SIZE + x) * 4;
            write(&mut out.lava, i, lava_px);
            write(&mut out.crust, i, crust_px);
            write(&mut out.basalt, i, basalt_px);
            write(&mut out.ash, i, ash_px);
        }
    }
    out
}

fn write(buf: &mut [u8], i: usize, c: [f32; 3]) {
    for (k, v) in c.into_iter().enumerate() {
        buf[i + k] = (clamp01(v) * 255.0).round() as u8;
    }
    buf[i + 3] = 255;
}

/// The molten `lava` texture as a repeating, unlit ground material (it reads as glowing regardless of scene
/// light, like `flame`'s boards): no original art to trace, generated instead.
pub fn lava_material(seed: u32, images: &mut Assets<Image>, materials: &mut Assets<StandardMaterial>) -> Handle<StandardMaterial> {
    let mut image = Image::new(
        Extent3d { width: SIZE as u32, height: SIZE as u32, depth_or_array_layers: 1 },
        TextureDimension::D2,
        generate(seed).lava,
        TextureFormat::Rgba8UnormSrgb,
        RenderAssetUsages::default(),
    );
    image.sampler = ImageSampler::Descriptor(ImageSamplerDescriptor {
        address_mode_u: ImageAddressMode::Repeat,
        address_mode_v: ImageAddressMode::Repeat,
        mag_filter: ImageFilterMode::Linear,
        min_filter: ImageFilterMode::Linear,
        ..default()
    });
    materials.add(StandardMaterial {
        base_color_texture: Some(images.add(image)),
        unlit: true,
        // Seen from either side, like `blueprint`'s own ground-draped mark: a steep flank can turn a cell's
        // triangle away from the camera. `depth_bias` keeps it from z-fighting the terrain it sits flush on.
        cull_mode: None,
        depth_bias: 20.0,
        // Per-vertex alpha (`ground_mesh_grid`'s own `colors`) fades a cell in and out instead of popping it to
        // full strength the instant it's added or removed (`arrival_alpha`/`fade_out_alpha`).
        alpha_mode: AlphaMode::Blend,
        ..default()
    })
}

/// How far above the true ground the patch sits, so it never z-fights with the terrain under it (`blueprint.rs`'s
/// own footprint mark uses the same lift).
const LIFT: f32 = 0.02;

/// The blend crossover between ash and glow (pop3-rev-analysis.md "Building ashes": ash is a fixed row 31/blend
/// 127, the 128-255 range above it, rows 32-63, is lava-exclusive and "presumably glowing") as a 0..1 fraction of
/// `u8::MAX`.
const GLOW_BLEND_THRESHOLD: f32 = 127.0 / 255.0;
/// Dark, cooling/ash colour multiplier at and below `GLOW_BLEND_THRESHOLD`. Our own two endpoint colours (the
/// original's own row colours "were not checked"), only the fact that it darkens to this and brightens to
/// `GLOW_TINT` is traced.
const ASH_TINT: [f32; 3] = [0.22, 0.08, 0.05];
/// Overexposed glow colour multiplier at full blend (0xFF): brighter than the procedural texture's own plain
/// colour (`[1.0; 3]`, at `GLOW_BLEND_THRESHOLD`) on purpose, an unlit "glows regardless of scene light" boost.
const GLOW_TINT: [f32; 3] = [1.5, 1.2, 0.85];

/// A cell's own colour multiplier from its `blend` alone (0-255): ashen and dark at and below
/// `GLOW_BLEND_THRESHOLD`, brightening smoothly through the texture's own plain colour up to an overexposed glow
/// at full blend — the whole "grows bright, cools dark, settles as ash" arc pop3-rev-analysis.md ("Building
/// ashes") describes, off nothing but this one value, exactly as the original's own single colour-table lookup is
/// (no separate pulse or timer of any kind).
fn glow_tint(blend: u8) -> [f32; 3] {
    let t = blend as f32 / 255.0;
    if t <= GLOW_BLEND_THRESHOLD {
        mix3(ASH_TINT, [1.0, 1.0, 1.0], smoothstep(0.0, GLOW_BLEND_THRESHOLD, t))
    } else {
        mix3([1.0, 1.0, 1.0], GLOW_TINT, smoothstep(GLOW_BLEND_THRESHOLD, 1.0, t))
    }
}

/// How long a freshly-arrived cell takes to fade in to full alpha: the original has no transparency in this path
/// at all (it repaints the opaque terrain texture outright, module doc), so this is purely our own cushion
/// against draping a translucent quad in at a hard pop — never a stand-in for `glow_tint`'s own arc.
const ARRIVAL_FADE_SECS: f32 = 0.3;

/// A cell's own fade-in alpha right now: full strength with no `arrival` (the initial seed disc, `Mode::Static`'s
/// fixed fissure, or any cell not just added by a spread step), easing in over `ARRIVAL_FADE_SECS` otherwise.
fn arrival_alpha(arrival: Option<CellArrival>, now: SimNow) -> f32 {
    match arrival {
        None => 1.0,
        Some(a) => smoothstep(0.0, ARRIVAL_FADE_SECS, now.secs_since(a.born)),
    }
}

/// The whole patch's own fade-out alpha right now: full strength outside a fixed-length cooling fade
/// (`game_core::lava::Lava::fade_progress`, `None` while still growing, already ash, or `Mode::Static`, whose own
/// `blend` already reaches zero on its own), easing down to 0 across it instead of riding `blend` alone (module
/// doc: a heavily-grown cell can still read as nearly full strength the turn before that fixed countdown abruptly
/// turns it to ash).
fn fade_out_alpha(fade_progress: Option<f32>) -> f32 {
    1.0 - fade_progress.unwrap_or(0.0)
}

/// `ground_mesh_grid`'s own corner order (`(ox, oz)`, 0 or 1 each) around a cell's own grid position.
const CORNERS: [(i32, i32); 4] = [(0, 0), (1, 0), (1, 1), (0, 1)];

/// One grid position's own look, shared by every quad that touches it (`ground_mesh_grid`): this sharing, not any
/// lava-specific blending, is the entire mechanism behind the module doc's "merged, organic blob" look.
#[derive(Clone, Copy)]
struct Vertex {
    alpha: f32,
    tint: [f32; 3],
}

impl Vertex {
    /// No lava here: fully transparent, so its own tint is never actually seen.
    const COLD: Vertex = Vertex { alpha: 0.0, tint: ASH_TINT };
}

/// One `Vertex` per currently-lit cell (`game_core::lava::Lava::cells_lit`), keyed by its own grid position: a
/// cell not in this map (a "gap" the simulation's own single-direction spread never pushed into) simply has no
/// entry, so `ground_mesh_grid`'s lookup falls back to `Vertex::COLD` for it and lets the quads around it carry
/// whatever brightness its lit neighbours give them.
fn lit_vertices(e: &Effect, now: SimNow) -> std::collections::HashMap<(i32, i32), Vertex> {
    match &e.kind {
        EffectKind::Lava(lava) => {
            let fade_out = fade_out_alpha(lava.fade_progress());
            lava.cells_lit().into_iter().map(|(pos, blend, arrival)| (pos, Vertex { alpha: arrival_alpha(arrival, now) * fade_out, tint: glow_tint(blend) })).collect()
        }
        _ => Default::default(),
    }
}

/// One quad per 1x1 cell square in `vertices`' own bounding box, padded by one cell on every side so a hot cell
/// right at the edge still fades toward cold neighbours (pop3-rev-analysis.md "Building ashes") instead of
/// stopping dead at the patch's own boundary. Each quad's 4 corners look up that exact grid position's `Vertex`
/// (`Vertex::COLD` where there is none) draped on the real terrain (`grounded::ground_point`, the same technique
/// `blueprint::grid_mark` uses for its footprint preview: the crater's funnel and the fissure's sunk disc are not
/// flat, so a single flat quad would float or bury itself across the patch) — a quad with every corner cold is
/// skipped outright, nothing to draw. UVs are absolute grid coordinates, not `0..1` per quad, so the repeating
/// material (`lava_material`) tiles seamlessly regardless of which cells are lit.
///
/// Each quad is split along the (1,0)-(0,1) diagonal, the same fold `terrain_mesh::build` uses for its own
/// cells: matching all 4 corners isn't enough on a slope — the other diagonal bends the quad's interior away
/// from the terrain's own triangle there, so it reads as sunk under the ground on one half of the cell.
fn ground_mesh_grid(vertices: &std::collections::HashMap<(i32, i32), Vertex>, terrain: &Heightmap, focus: Vec2, params: &crate::terrain_mesh::CurveParams) -> MeshData {
    let mut m = MeshData::default();
    if vertices.is_empty() {
        return m;
    }
    let (min_x, max_x) = (vertices.keys().map(|&(x, _)| x).min().unwrap() - 1, vertices.keys().map(|&(x, _)| x).max().unwrap() + 1);
    let (min_z, max_z) = (vertices.keys().map(|&(_, z)| z).min().unwrap() - 1, vertices.keys().map(|&(_, z)| z).max().unwrap() + 1);

    for cz in min_z..max_z {
        for cx in min_x..max_x {
            let corners: [Vertex; 4] = CORNERS.map(|(ox, oz)| vertices.get(&(cx + ox, cz + oz)).copied().unwrap_or(Vertex::COLD));
            if corners.iter().all(|c| c.alpha <= 0.0) {
                continue;
            }
            let base = m.positions.len() as u32;
            for (k, (ox, oz)) in CORNERS.into_iter().enumerate() {
                let at = Vec2::new((cx + ox) as f32, (cz + oz) as f32);
                let p = ground_point(terrain, focus, params, at) + Vec3::Y * LIFT;
                let v = corners[k];
                m.positions.push(p.into());
                m.normals.push([0.0, 1.0, 0.0]);
                m.uvs.push([at.x, at.y]);
                m.colors.push([v.tint[0], v.tint[1], v.tint[2], v.alpha]);
            }
            m.indices.extend([base, base + 1, base + 3, base + 1, base + 2, base + 3]);
        }
    }
    m
}

fn set_ground_mesh(mesh: &mut Mesh, data: MeshData) {
    mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, data.positions);
    mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, data.normals);
    mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, data.uvs);
    mesh.insert_attribute(Mesh::ATTRIBUTE_COLOR, data.colors);
    mesh.insert_indices(Indices::U32(data.indices));
}

/// One lava effect's own ground patch: a draped, textured mesh rebuilt every frame (like `blueprint`'s
/// footprint mark) so it tracks the camera's own live focus and the torus wrap, and the live cell set
/// (`Lava::cells`, which grows and later shrinks to nothing as the effect lives out its own lifecycle) — no
/// `Grounded` here, its vertices are already render-space positions.
#[derive(Component)]
pub struct LavaView {
    mesh: Handle<Mesh>,
}

impl WorldView for LavaView {
    type Model = (Id<Effect>, Effect);
    type Params = (Res<'static, CurrentMap>, Res<'static, CameraRig>, Res<'static, CurveParamsRes>, ResMut<'static, Assets<Mesh>>, ResMut<'static, Assets<StandardMaterial>>, ResMut<'static, Assets<Image>>);

    fn models(map: &GameMap) -> impl Iterator<Item = &(Id<Effect>, Effect)> {
        map.effects.entries().filter(|(_, e)| matches!(e.kind, EffectKind::Lava(_)))
    }

    fn id((id, _): &(Id<Effect>, Effect)) -> u32 {
        id.raw()
    }

    fn spawn((id, e): &(Id<Effect>, Effect), view: &mut EntityCommands, (map, rig, params, meshes, mats, images): &mut SystemParamItem<Self::Params>) -> Option<Self> {
        // `spawn` only ever sees a freshly-created effect, whose cells are always the initial seed (never an
        // actual spread step yet) — so every one carries `arrival: None`, and `arrival_alpha` never reads `now`
        // on this path: a placeholder is safe here. `update` (below) passes its own real `now`.
        let vertices = lit_vertices(e, SimNow::default());
        if vertices.is_empty() {
            return None;
        }
        let mut mesh = Mesh::new(PrimitiveTopology::TriangleList, RenderAssetUsages::default());
        set_ground_mesh(&mut mesh, ground_mesh_grid(&vertices, &map.0.terrain, rig.focus, &params.0));
        let mesh = meshes.add(mesh);
        let material = lava_material(id.raw(), images, mats);
        view.insert((Mesh3d(mesh.clone()), MeshMaterial3d(material), Transform::default(), Visibility::Visible, NotShadowCaster, crate::hover::NoOutline));
        Some(LavaView { mesh })
    }

    fn update(&self, (_, e): &(Id<Effect>, Effect), now: SimNow, (map, rig, params, meshes, _, _): &mut SystemParamItem<Self::Params>) {
        let vertices = lit_vertices(e, now);
        if let Some(mut m) = meshes.get_mut(&self.mesh) {
            set_ground_mesh(&mut m, ground_mesh_grid(&vertices, &map.0.terrain, rig.focus, &params.0));
        }
    }
}

pub struct LavaPlugin;

impl Plugin for LavaPlugin {
    fn build(&self, app: &mut App) {
        app.add_systems(Update, sync_views::<LavaView>.after(crate::units::run_ticks));
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use game_core::time::{Tick, TICKS_PER_SECOND};

    #[test]
    fn rng_is_deterministic_and_in_range() {
        let (mut a, mut b) = (Rng(7), Rng(7));
        let (va, vb) = (a.next(), b.next());
        assert_eq!(va, vb);
        assert!((0.0..1.0).contains(&va));
        assert_ne!(Rng(7).next(), Rng(8).next());
    }

    #[test]
    fn perlin_wraps_seamlessly_on_its_period() {
        let noise = make_noise(962337);
        for (x, y) in [(0.3, 0.6), (2.7, 1.1), (3.99, 0.0)] {
            assert!((noise.perlin(x, y, 4) - noise.perlin(x + 4.0, y, 4)).abs() < 1e-5, "wraps on x");
            assert!((noise.perlin(x, y, 4) - noise.perlin(x, y + 4.0, 4)).abs() < 1e-5, "wraps on y");
        }
    }

    #[test]
    fn worley_wraps_seamlessly_on_its_grid() {
        let w = make_worley(1, 8);
        for (u, v) in [(0.1, 0.2), (0.45, 0.9)] {
            let a = w.sample(u, v);
            let b = w.sample(u + 1.0, v);
            assert!((a.0 - b.0).abs() < 1e-4 && (a.1 - b.1).abs() < 1e-4);
        }
    }

    #[test]
    fn ramp_runs_dark_to_the_core_and_stays_in_range() {
        assert_eq!(ramp(0.0), DARK);
        assert_eq!(ramp(1.0), CORE);
        for i in 0..=100 {
            let c = ramp(i as f32 / 100.0);
            assert!(c.iter().all(|&v| (0.0..=1.0).contains(&v)));
        }
    }

    #[test]
    fn generate_is_deterministic_and_the_right_shape() {
        let a = generate(962337);
        let b = generate(962337);
        assert_eq!(a.lava, b.lava);
        for buf in [&a.lava, &a.crust, &a.basalt, &a.ash] {
            assert_eq!(buf.len(), SIZE * SIZE * 4);
            assert!(buf.chunks_exact(4).all(|p| p[3] == 255), "opaque");
        }
        assert_ne!(a.lava, generate(1).lava, "a different seed, a different flow");
        assert_ne!(a.lava, a.crust, "distinct textures");
    }

    fn vmap(entries: &[((i32, i32), Vertex)]) -> std::collections::HashMap<(i32, i32), Vertex> {
        entries.iter().copied().collect()
    }

    const FULL: Vertex = Vertex { alpha: 1.0, tint: [1.0, 1.0, 1.0] };

    #[test]
    fn ground_mesh_grid_is_empty_with_no_lit_vertices() {
        let terrain = Heightmap::new(16);
        let params = crate::terrain_mesh::CurveParams::default();
        let m = ground_mesh_grid(&vmap(&[]), &terrain, Vec2::ZERO, &params);
        assert!(m.positions.is_empty() && m.indices.is_empty());
    }

    #[test]
    fn ground_mesh_grid_draws_every_quad_touching_a_single_lit_vertex_and_no_other() {
        let terrain = Heightmap::new(16);
        let params = crate::terrain_mesh::CurveParams::default();
        let m = ground_mesh_grid(&vmap(&[((5, 5), FULL)]), &terrain, Vec2::ZERO, &params);
        // A single vertex is a corner of exactly 4 quads (lower-left at (4,4),(5,4),(4,5),(5,5)): every one of
        // them has that vertex as a corner, so none is all-cold and none gets skipped — a one-cell fade ring,
        // exactly enough to cover every quad this vertex can possibly reach (a quad any further out never touches
        // it at all, so padding beyond this would only ever add more cold, invisible geometry).
        assert_eq!(m.indices.len() / 6, 4, "exactly the 4 quads touching (5,5)");
        assert!(m.uvs.contains(&[5.0, 5.0]), "the lit vertex's own uv is in there");
    }

    #[test]
    fn ground_mesh_grid_shares_one_vertex_s_own_value_across_every_quad_touching_it() {
        // Two lit cells one cell apart share a quad between them: that shared quad's corners must show each
        // cell's own value, not some blended or uniform guess — this sharing is the whole merged-blob mechanism
        // (module doc, pop3-rev-analysis.md "Building ashes").
        let terrain = Heightmap::new(16);
        let params = crate::terrain_mesh::CurveParams::default();
        let bright = Vertex { alpha: 1.0, tint: [1.0, 1.0, 1.0] };
        let dim = Vertex { alpha: 0.3, tint: [1.0, 1.0, 1.0] };
        let m = ground_mesh_grid(&vmap(&[((0, 0), bright), ((2, 0), dim)]), &terrain, Vec2::ZERO, &params);
        let alpha_at = |uv: [f32; 2]| m.uvs.iter().position(|&u| u == uv).map(|i| m.colors[i][3]);
        assert_eq!(alpha_at([0.0, 0.0]), Some(1.0), "cell (0,0)'s own corner");
        assert_eq!(alpha_at([2.0, 0.0]), Some(0.3), "cell (2,0)'s own corner");
        assert_eq!(alpha_at([1.0, 0.0]), Some(0.0), "the cell between them, cold: never lit itself");
    }

    #[test]
    fn ground_mesh_grid_skips_a_quad_with_every_corner_cold() {
        let terrain = Heightmap::new(16);
        let params = crate::terrain_mesh::CurveParams::default();
        // Two lit cells far enough apart that none of the (padded) bounding box's many quads between them ever
        // touches either one: only the 4+4 quads actually touching a lit vertex should be drawn.
        let m = ground_mesh_grid(&vmap(&[((0, 0), FULL), ((20, 20), FULL)]), &terrain, Vec2::ZERO, &params);
        assert_eq!(m.indices.len() / 6, 8, "4 quads around each lit vertex, nothing in between");
    }

    #[test]
    fn ground_mesh_grid_splits_quads_along_the_terrain_s_own_diagonal() {
        // Every quad is split (1,0)-(0,1) (indices 1 and 3 of each 4), the same fold `terrain_mesh::build` uses:
        // matching all 4 corners isn't enough on a slope if the two meshes fold their quads differently.
        let terrain = Heightmap::new(16);
        let params = crate::terrain_mesh::CurveParams::default();
        let m = ground_mesh_grid(&vmap(&[((0, 0), FULL)]), &terrain, Vec2::ZERO, &params);
        assert!(m.indices.chunks(6).all(|q| q.to_vec() == vec![q[0], q[0] + 1, q[0] + 3, q[0] + 1, q[0] + 2, q[0] + 3]));
    }

    #[test]
    fn ground_mesh_grid_lifts_every_corner_off_flat_ground() {
        let terrain = Heightmap::new(16);
        let params = crate::terrain_mesh::CurveParams { curvature: 0.0, ..crate::terrain_mesh::CurveParams::default() };
        let m = ground_mesh_grid(&vmap(&[((0, 0), FULL)]), &terrain, Vec2::ZERO, &params);
        assert!(m.positions.iter().all(|p| (p[1] - LIFT).abs() < 1e-4), "flat, uncurved ground: every corner at exactly LIFT");
    }

    #[test]
    fn glow_tint_is_ashen_and_dark_at_blend_zero_and_bright_at_full_blend() {
        assert_eq!(glow_tint(0), ASH_TINT);
        assert_eq!(glow_tint(255), GLOW_TINT);
    }

    #[test]
    fn glow_tint_crosses_the_plain_texture_colour_right_at_the_ash_glow_threshold() {
        let at_threshold = (GLOW_BLEND_THRESHOLD * 255.0).round() as u8;
        let t = glow_tint(at_threshold);
        for c in t {
            assert!((c - 1.0).abs() < 0.02, "near [1,1,1] right at the crossover: {t:?}");
        }
    }

    #[test]
    fn glow_tint_ramps_steadily_within_each_of_its_two_segments() {
        let at_threshold = (GLOW_BLEND_THRESHOLD * 255.0).round() as u8;
        // Below the crossover: each channel moves steadily from ASH_TINT towards [1,1,1], never backtracking.
        let mut prev = glow_tint(0);
        for b in 1..=at_threshold {
            let t = glow_tint(b);
            for i in 0..3 {
                assert!(t[i] >= prev[i] - 1e-6, "ash segment backtracked on channel {i} at blend {b}: {prev:?} -> {t:?}");
            }
            prev = t;
        }
        // Above it: each channel moves steadily towards GLOW_TINT, in whichever direction that endpoint is.
        let mut prev = glow_tint(at_threshold);
        for b in at_threshold..=255 {
            let t = glow_tint(b);
            for i in 0..3 {
                let towards_glow = if GLOW_TINT[i] >= prev[i] { t[i] >= prev[i] - 1e-6 } else { t[i] <= prev[i] + 1e-6 };
                assert!(towards_glow, "glow segment backtracked on channel {i} at blend {b}: {prev:?} -> {t:?}");
            }
            prev = t;
        }
    }

    #[test]
    fn arrival_alpha_is_full_strength_with_no_arrival() {
        assert_eq!(arrival_alpha(None, SimNow::default()), 1.0);
    }

    #[test]
    fn arrival_alpha_fades_in_over_arrival_fade_secs() {
        let arrival = CellArrival { born: Tick::from_wire(0) };
        let at = |secs: f32| arrival_alpha(Some(arrival), SimNow { tick: Tick::from_wire((secs * TICKS_PER_SECOND as f32) as u32), frac: 0.0 });
        assert_eq!(at(0.0), 0.0, "not yet, right as it arrives");
        let mid = at(ARRIVAL_FADE_SECS / 2.0);
        assert!(mid > 0.0 && mid < 1.0, "partway through: {mid}");
        assert_eq!(at(ARRIVAL_FADE_SECS * 2.0), 1.0, "settled, well past the fade");
    }

    #[test]
    fn fade_out_alpha_is_full_strength_outside_a_cooling_fade() {
        assert_eq!(fade_out_alpha(None), 1.0);
    }

    #[test]
    fn fade_out_alpha_runs_from_full_strength_down_to_zero_across_the_fade() {
        assert_eq!(fade_out_alpha(Some(0.0)), 1.0, "just started cooling: still full strength");
        assert_eq!(fade_out_alpha(Some(0.5)), 0.5, "halfway through");
        assert_eq!(fade_out_alpha(Some(1.0)), 0.0, "the turn it becomes ash: fully faded");
    }
}
